def deserialize(cls, val):
    if isinstance(val, int):
        return val
    if "(" not in val and val in cls.qmk_id_to_keycode:
        return cls.qmk_id_to_keycode[val].code
    if "(" in val and ")" in val:
        # Process macro-like keycodes
        macro_key = val.split("(")[0].strip()
        if macro_key in cls.qmk_id_to_keycode:
            return cls.qmk_id_to_keycode[macro_key].code
    return 0
